#!/usr/bin/env python3
"""Execute every checker and collect PER-CASE results. The observation layer for B3/B5.

    python tools/verification_run.py                  run everything, print a summary
    python tools/verification_run.py --json out.json  write the run record

WHY THIS EXISTS AS ITS OWN LAYER. HUG-VER-003 requires the verification report to be
"generated by executing all checkers against the release candidate", and B3 requires the
traceability matrix to name the EXECUTED case that verifies each requirement. Both need
the same thing: a list of cases that actually ran, each with its identifier and its
outcome. Read the spec instead and you get a report that describes a suite rather than
one that observed it — the failure the record already names, and the one this repo has
walked into before under other shapes (OF-008: a control satisfied by a SyntaxError;
D-009: a check certifying the bug because its red case moved the wrong variable).

So: nothing here reads a requirement document, a docstring, or a summary line. It runs
the cases and writes down what happened.

THE VERDICT VOCABULARY IS NOT DECORATION. Two kinds of statement live in a run record
and must never be conflated:

    PASS / FAIL             speak about THE SUBJECT. The case observed its subject and
                            the subject was sound, or was not.
    INSTRUMENT_FAULT        speaks about THE OBSERVER. The case could not make its
    READ_FAULT              observation — it raised, its fixture broke, its read path
                            failed. The subject's status is NOT ESTABLISHED by this run.
    NO_RECORD               speaks about THE RUN. No observation was attempted at all:
                            skipped, never collected, never executed.

An INSTRUMENT_FAULT counted as a FAIL slanders the subject. Counted as a PASS it is
worse. Ruled at D-011 for the evidence harness and D-012 for the monitor; the same
vocabulary governs here because it is the same distinction.

unittest already draws the line this layer needs and most callers throw it away:
`addFailure` is an assertion that did not hold (a statement about the subject) while
`addError` is an exception escaping the case (a statement about the case itself). They
are mapped to FAIL and INSTRUMENT_FAULT respectively, and not merged.

EMPTY IS LOUD. A run that collects no cases is the most dangerous result this file can
produce, because every downstream table renders identically to a clean run — every row
simply reports nothing, and nothing is what an unexercised requirement also reports.
`collect()` refuses to return a record with no cases, and refuses one whose suite counts
fall below the floors recorded at the bottom of this file.
"""
import argparse
import importlib
import io
import json
import os
import platform
import re
import subprocess
import sys
import time
import unittest
from contextlib import redirect_stdout
from pathlib import Path

REPO = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(REPO / "tools"))
sys.path.insert(0, str(REPO / "tools" / "checkers"))
sys.path.insert(0, str(REPO / "tests"))
sys.path.insert(0, str(REPO))

#: The outcome vocabulary, and which side of the subject/observer line each sits on.
SUBJECT_OUTCOMES = ("PASS", "FAIL")
OBSERVER_OUTCOMES = ("INSTRUMENT_FAULT", "READ_FAULT", "NO_RECORD")
OUTCOMES = SUBJECT_OUTCOMES + OBSERVER_OUTCOMES


def established(outcome):
    """Did this case establish anything about its subject?

    The one predicate every consumer of a run record needs and the one most likely to
    be written wrong. An INSTRUMENT_FAULT is not a failing subject and not a passing
    one: it is a run that did not look.
    """
    return outcome in SUBJECT_OUTCOMES


class _Collector(unittest.TestResult):
    """Records every case's identifier and outcome instead of only counting them."""

    def __init__(self):
        super().__init__()
        self.cases = {}
        self._started = {}

    # --- identity and declarations, read off the LOADED test object.
    #
    # Not scraped from source text. A requirement id in a module docstring would
    # attribute that requirement to every test in the file, and a docstring that
    # mentions a requirement only to say it is NOT covered here would attribute it
    # backwards. The object that ran is asked what it claims to verify.
    @staticmethod
    def _declarations(test):
        method = getattr(test, getattr(test, "_testMethodName", ""), None)
        cls = type(test)

        def pick(attr):
            for holder, scope in ((method, "method"), (cls, "class")):
                value = getattr(holder, attr, None)
                if value:
                    return value, scope
            return None, None

        verifies, vscope = pick("verifies")
        polarity, pscope = pick("polarity")
        if isinstance(verifies, str):
            verifies = (verifies,)
        if polarity is None:
            polarity, pscope = _infer_polarity(getattr(test, "_testMethodName", "")), "name"
        return {
            "verifies": sorted(set(verifies or ())),
            "verifies_scope": vscope,
            "polarity": polarity,
            "polarity_source": pscope if polarity else None,
        }

    def startTest(self, test):
        super().startTest(test)
        self._started[test.id()] = time.time()

    def _record(self, test, outcome, detail=None):
        cid = test.id()
        entry = {
            "case_id": cid,
            "kind": "test",
            "outcome": outcome,
            "detail": detail,
            "duration_s": round(time.time() - self._started.get(cid, time.time()), 4),
        }
        entry.update(self._declarations(test))
        self.cases[cid] = entry

    def addSuccess(self, test):
        super().addSuccess(test)
        self._record(test, "PASS")

    def addFailure(self, test, err):
        # An assertion that did not hold: a statement about the SUBJECT.
        super().addFailure(test, err)
        self._record(test, "FAIL", self._exc_line(err))

    def addError(self, test, err):
        # An exception escaping the case: a statement about the CASE. The subject's
        # status is not established, so this is never folded into FAIL.
        super().addError(test, err)
        self._record(test, "INSTRUMENT_FAULT", self._exc_line(err))

    def addSkip(self, test, reason):
        super().addSkip(test, reason)
        self._record(test, "NO_RECORD", f"skipped: {reason}")

    def addExpectedFailure(self, test, err):
        super().addExpectedFailure(test, err)
        self._record(test, "PASS", "expected failure")

    def addUnexpectedSuccess(self, test):
        super().addUnexpectedSuccess(test)
        self._record(test, "FAIL", "unexpected success")

    @staticmethod
    def _exc_line(err):
        return f"{err[0].__name__}: {str(err[1])[:300]}"


def _infer_polarity(name):
    """Polarity from a method name, only where the name states it unambiguously.

    Returned with polarity_source='name' so a consumer can tell a case that DECLARED
    its polarity from one whose polarity was read off its name. A name is a weaker
    claim than a declaration and the matrix shows which it had; guessing silently is
    how a suite ends up reporting red coverage it never had.
    """
    n = f"_{name.lower()}_"
    # The idioms this suite actually uses for "demonstrate it fails on a violation".
    # `would_catch` is the explicit one (test_the_scan_would_catch_a_violation);
    # `both_polarities` names a case that carries its own red half.
    red_marks = ("_red_", "_catches_", "_refuses_", "_refused_", "_rejects_",
                 "_rejected_", "_would_catch_", "_is_caught_", "_are_caught_",
                 "_raises_rather_than_", "_both_polarities_", "_corrupted_",
                 "_corrupt_", "_undefined_", "_tampered_")
    green_marks = ("_green_", "_accepts_", "_accepted_", "_holds_", "_held_")
    red = any(m in n for m in red_marks)
    green = any(m in n for m in green_marks)
    # "at both polarities" is red AND green; it satisfies a red-case demand.
    if "_both_polarities_" in n:
        return "red"
    if red and not green:
        return "red"
    if green and not red:
        return "green"
    return None


def _import_failures(suite, out):
    """unittest turns a module that failed to import into a case that raises on run.

    Left unhandled these look like ordinary errors; named here because an import
    failure means a whole FILE of cases did not execute, and the requirements those
    cases carried will silently report nothing rather than reporting a fault.
    """
    for test in _flatten(suite):
        cls = type(test).__name__
        if cls in ("_FailedTest", "ModuleImportFailure"):
            out.append(test.id())


def _flatten(suite):
    for item in suite:
        if isinstance(item, unittest.TestSuite):
            yield from _flatten(item)
        else:
            yield item


def run_tests(repo=REPO):
    """Execute the unittest suites and return (cases, meta)."""
    loader = unittest.TestLoader()
    suite = loader.discover(start_dir=str(repo / "tests"), pattern="test_*.py",
                            top_level_dir=str(repo / "tests"))
    broken_imports = []
    _import_failures(suite, broken_imports)
    collected = len(list(_flatten(suite)))

    result = _Collector()
    buf = io.StringIO()
    started = time.time()
    with redirect_stdout(buf):
        suite.run(result)
    return list(result.cases.values()), {
        "collected": collected,
        "executed": len(result.cases),
        "broken_imports": broken_imports,
        "loader_errors": [str(e) for e in getattr(loader, "errors", [])],
        "duration_s": round(time.time() - started, 2),
    }


class UnmappedCheck(Exception):
    """A check exists that no CHECK_VERIFIES entry accounts for."""


def run_checkers(repo=REPO):
    """Execute both checkers' checks and both checkers' red/green self-test cases."""
    cases = []
    for module_name, arg in (("design_record_consistency", repo),
                             ("defs_generation", repo)):
        mod = importlib.import_module(module_name)
        # A check added without an entry here would contribute to no requirement and
        # say so nowhere — the silent gap the build forbids. Refused loudly instead.
        unmapped = [cid for cid, _n, _f in mod.CHECKS if cid not in mod.CHECK_VERIFIES]
        if unmapped:
            raise UnmappedCheck(
                f"{module_name}: {unmapped} appear in CHECKS but not in "
                f"CHECK_VERIFIES. Map each to the requirements it discharges, or to "
                f"an empty tuple if it discharges none — but say which.")
        buf = io.StringIO()
        with redirect_stdout(buf):
            for c in mod.iter_check_cases(arg):
                cases.append({
                    "case_id": f"{module_name}:{c['case_id']}",
                    "kind": "check",
                    "outcome": ("INSTRUMENT_FAULT" if c["raised"]
                                else "PASS" if c["passed"] else "FAIL"),
                    "detail": c["evidence"][:300],
                    "verifies": sorted(mod.CHECK_VERIFIES.get(c["case_id"], ())),
                    "verifies_scope": "checker",
                    "polarity": None, "polarity_source": None,
                    "checker": module_name,
                })
            for c in mod.iter_selftest_cases(arg):
                cases.append({
                    "case_id": f"{module_name}:{c['case_id']}",
                    "kind": "mutation",
                    # The self-test's subject is the CHECK: did the red case turn it
                    # red, did the green case leave it green. Its outcome is a
                    # statement about the check, which is the subject here.
                    "outcome": "PASS" if c["passed"] else "FAIL",
                    "detail": f"{c['label']} on {c['target']}",
                    # A mutation case is the RED CASE FOR its check, so it carries that
                    # check's requirements. This is what makes B4/HUG-VER-002 answerable
                    # per requirement — "does this requirement have a demonstrated red
                    # case" — rather than only per checker.
                    "verifies": sorted(mod.CHECK_VERIFIES.get(c["check"], ())),
                    "verifies_scope": "checker",
                    "polarity": c["polarity"],
                    "polarity_source": "declared",
                    "checker": module_name,
                    "covers_check": f"{module_name}:{c['check']}",
                    # OF-008's shape, surfaced rather than buried: a red case that
                    # owes its result to an exception rather than to the check
                    # detecting the violation it was written for.
                    "passed_by_exception": bool(c["raised"]),
                })
    return cases


def _manifest_field(text, label):
    """One `| Label | value |` cell out of a demonstration manifest."""
    m = re.search(rf"^\|\s*{re.escape(label)}\s*\|\s*(.+?)\s*\|\s*$",
                  text, re.MULTILINE)
    return m.group(1).strip().strip("*`") if m else None


def run_demonstrations(repo=REPO):
    """Read the archived demonstration attempts (B6/B7/B10/B11/B14).

    A demonstration is how a D-verified requirement is discharged: HUG-SYS-006,
    HUG-GND-004 and HUG-UI-004 cannot be settled by a unit test, and the record says
    so — "D = Demonstration (documented pass execution)".

    BE PRECISE ABOUT WHAT THIS IS. Reading a manifest is NOT executing a
    demonstration; it is reading the record of one that ran at a stated time. What
    makes that record admissible NOW, in this run, is two things that ARE executed
    here: `tools/verify_evidence.py` recomputes every archived digest, and the
    verdict suites (tests/test_b6_verdict.py, tests/test_b11_verdict.py) recompute
    the verdict from the archived bytes. So the matrix cites the attempt AND the
    executed cases that re-establish it, never the attempt alone. Ruled at D-012:
    the verdict must be computable from the archived evidence alone.

    An attempt whose manifest names no requirement is a finding, not a skip.
    """
    cases = []
    root = repo / "verification" / "evidence"
    if not root.is_dir():
        return cases
    for attempt in sorted(root.glob("*/attempt-*")):
        manifest = attempt / "MANIFEST.md"
        rel = attempt.relative_to(repo).as_posix()
        if not manifest.is_file():
            cases.append({
                "case_id": rel, "kind": "demonstration",
                "outcome": "NO_RECORD",
                "detail": "attempt directory with no MANIFEST.md",
                "verifies": [], "verifies_scope": None,
                "polarity": None, "polarity_source": None,
            })
            continue
        text = manifest.read_text(encoding="utf-8")
        result = (_manifest_field(text, "Result") or "").upper()
        req = _manifest_field(text, "Requirement")
        reqs = re.findall(r"\bHUG-[A-Z]+-\d{3}\b", req or "")
        cases.append({
            "case_id": rel,
            "kind": "demonstration",
            # The manifest's recorded outcome is authoritative — the runner's summary
            # is not (that disagreement is what the Phase 3 apparatus fix settled).
            "outcome": result if result in OUTCOMES else "NO_RECORD",
            "detail": f"{_manifest_field(text, 'Obligation') or '?'}: "
                      f"{(_manifest_field(text, 'What it demonstrates') or '')[:180]}",
            "verifies": sorted(set(reqs)),
            "verifies_scope": "manifest",
            "polarity": None, "polarity_source": None,
            "obligation": _manifest_field(text, "Obligation"),
            "finished_utc": _manifest_field(text, "Finished (UTC)"),
        })
    return cases


def _git(repo, *args, strip=True):
    """Run git and return stdout, or None.

    `strip` is not a convenience default: `git status --porcelain` puts the index
    status in column 1, so stripping the output eats the leading space of the FIRST
    line only and shifts that one path by a character. It produced 'ools/checkers/...'
    beside a correct 'tools/checkers/...' in the same list — a corruption that looks
    like a typo rather than a bug, in the one field whose job is to say whether the
    tree the run measured is the tree the commit names.
    """
    try:
        out = subprocess.run(["git", "-C", str(repo)] + list(args),
                             capture_output=True, text=True, encoding="utf-8",
                             errors="replace", timeout=30)
        if out.returncode != 0:
            return None
        return out.stdout.strip() if strip else out.stdout
    except (OSError, subprocess.SubprocessError):
        return None


def run_metadata(repo=REPO):
    """What was run, against what. HUG-VER-003 requires the report carry it."""
    status = _git(repo, "status", "--porcelain", strip=False)
    return {
        "commit": _git(repo, "rev-parse", "HEAD"),
        "commit_subject": _git(repo, "log", "-1", "--format=%s"),
        "tree_clean": (status.strip() == "") if status is not None else None,
        "dirty_paths": [ln[3:] for ln in (status or "").splitlines() if ln][:40],
        "executed_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "python": sys.version.split()[0],
        "platform": platform.platform(),
        "repo": str(repo),
    }


#: Floors. A run that collects fewer cases than the build is known to carry did not
#: execute the suite — it found a broken import, a renamed directory, or a discovery
#: root that matched nothing. Without a floor that failure renders as an empty table,
#: which is indistinguishable from a suite that ran and verified nothing. Raise these
#: when the suite grows; never lower one to make a run pass.
FLOOR_TESTS = 482      # 492 with the entry on an annunciation (D-018); 471 at 481
                       # (D-016, D-017), 455 at 465 (the pass plan), 430 at 437
                       # (D-015), 420 at 427 (D-013), 380 at 396
FLOOR_CHECKS = 32
FLOOR_MUTATIONS = 120


class EmptyRun(Exception):
    """Raised when a run did not observe enough to be evidence of anything."""


def collect(repo=REPO, enforce_floors=True):
    """Run everything. Returns the run record, or raises EmptyRun."""
    test_cases, test_meta = run_tests(repo)
    checker_cases = run_checkers(repo)
    demo_cases = run_demonstrations(repo)
    cases = test_cases + checker_cases + demo_cases

    counts = {
        "test": sum(1 for c in cases if c["kind"] == "test"),
        "check": sum(1 for c in cases if c["kind"] == "check"),
        "mutation": sum(1 for c in cases if c["kind"] == "mutation"),
        "demonstration": sum(1 for c in cases if c["kind"] == "demonstration"),
    }
    if enforce_floors:
        shortfalls = [
            f"{kind}: {counts[kind]} < floor {floor}"
            for kind, floor in (("test", FLOOR_TESTS), ("check", FLOOR_CHECKS),
                                ("mutation", FLOOR_MUTATIONS))
            if counts[kind] < floor
        ]
        if shortfalls:
            raise EmptyRun(
                "the run collected fewer cases than this build carries, so it did not "
                "execute the suite: " + "; ".join(shortfalls)
                + (f"; broken imports: {test_meta['broken_imports']}"
                   if test_meta["broken_imports"] else "")
                + ". This is reported as an INSTRUMENT_FAULT for the whole run, not as "
                  "an empty pass.")

    # Executed-now and archived are counted apart. An INSTRUMENT_FAULT preserved from
    # a demonstration attempt in August is a record of what happened then, not an
    # observation this run made — the append-only attempt layout exists precisely so
    # those stay visible, and folding them into this run's totals would make every
    # future run report a fault it did not have. What the CURRENT run owes is that
    # each obligation has a passing attempt somewhere in its history; that is checked
    # by `obligations` below, not by counting faults.
    by_outcome, archived_by_outcome = {}, {}
    for c in cases:
        bucket = archived_by_outcome if c["kind"] == "demonstration" else by_outcome
        bucket[c["outcome"]] = bucket.get(c["outcome"], 0) + 1

    obligations = {}
    for c in cases:
        if c["kind"] != "demonstration":
            continue
        ob = c.get("obligation") or c["case_id"].split("/")[2]
        entry = obligations.setdefault(ob, {"attempts": [], "passing": None})
        entry["attempts"].append({"attempt": c["case_id"], "outcome": c["outcome"]})
        if c["outcome"] == "PASS":
            entry["passing"] = c["case_id"]

    return {
        "schema": "huginn-verification-run/1",
        "metadata": run_metadata(repo),
        "test_meta": test_meta,
        "counts": counts,
        "by_outcome": by_outcome,
        "archived_by_outcome": archived_by_outcome,
        "obligations": obligations,
        "cases": cases,
    }


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--json", metavar="PATH", help="write the run record here")
    args = ap.parse_args(argv)
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    except (AttributeError, OSError):  # pragma: no cover
        pass

    try:
        record = collect()
    except EmptyRun as exc:
        print(f"[INSTRUMENT_FAULT] {exc}")
        return 2

    c, o = record["counts"], record["by_outcome"]
    unmet = [ob for ob, v in record["obligations"].items() if not v["passing"]]
    print(f"{sum(c.values())} cases: {c['test']} tests, {c['check']} checks, "
          f"{c['mutation']} red/green mutation cases, "
          f"{c['demonstration']} archived demonstrations")
    for name in OUTCOMES:
        if o.get(name):
            side = "subject" if name in SUBJECT_OUTCOMES else "observer/run"
            print(f"  {name:<17} {o[name]:>4}   ({side})")
    faults = [x for x in record["cases"]
              if x["kind"] != "demonstration" and not established(x["outcome"])]
    for f in faults[:20]:
        print(f"    {f['outcome']}: {f['case_id']} — {f['detail']}")
    print("  archived demonstrations (records of past runs, not this run's "
          f"observations): {record['archived_by_outcome']}")
    for ob, v in sorted(record["obligations"].items()):
        mark = v["passing"] or "NO PASSING ATTEMPT"
        print(f"    {ob:<4} {len(v['attempts'])} attempt(s) -> {mark}")
    if unmet:
        print(f"  OBLIGATIONS WITH NO PASSING ATTEMPT: {unmet}")

    if args.json:
        Path(args.json).write_text(
            json.dumps(record, indent=2, sort_keys=False), encoding="utf-8")
        print(f"wrote {args.json}")
    # Non-zero when anything EXECUTED THIS RUN failed or faulted, or when an
    # obligation has no passing attempt anywhere in its preserved history.
    return 1 if (o.get("FAIL") or o.get("INSTRUMENT_FAULT") or o.get("READ_FAULT")
                 or unmet) else 0


if __name__ == "__main__":
    sys.exit(main())
